import{_ as l,a0 as p,w as d,s as o,ao as h,I as n,x as i,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 中一次重命名多个文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中一次重命名多个文件 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中一次重命名多个文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中一次重命名多个文件 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180615 How To Rename Multiple Files At Once In Linux","title":"如何在 Linux 中一次重命名多个文件","tag":"201810","desc":""},"relativePath":"201810/20180615 How To Rename Multiple Files At Once In Linux.md","filePath":"[post].md"}'),c={name:"201810/20180615 How To Rename Multiple Files At Once In Linux.md"};function r(g,s,u,k,b,x){const t=p("Link");return d(),o("div",null,[s[15]||(s[15]=h(`<h1 id="如何在-linux-中一次重命名多个文件" tabindex="-1">如何在 Linux 中一次重命名多个文件 <a class="header-anchor" href="#如何在-linux-中一次重命名多个文件" aria-label="Permalink to “如何在 Linux 中一次重命名多个文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/06/Rename-Multiple-Files-720x340.png" alt=""></p><p>你可能已经知道，我们使用 <code>mv</code> 命令在类 Unix 操作系统中重命名或者移动文件和目录。 但是，<code>mv</code> 命令不支持一次重命名多个文件。 不用担心。 在本教程中，我们将学习使用 Linux 中的 <code>mmv</code> 命令一次重命名多个文件。 此命令用于在类 Unix 操作系统中使用标准通配符批量移动、复制、追加和重命名文件。</p><h3 id="在-linux-中一次重命名多个文件" tabindex="-1">在 Linux 中一次重命名多个文件 <a class="header-anchor" href="#在-linux-中一次重命名多个文件" aria-label="Permalink to “在 Linux 中一次重命名多个文件”">​</a></h3><p><code>mmv</code> 程序可在基于 Debian 的系统的默认仓库中使用。 要想在 Debian、Ubuntu、Linux Mint 上安装它，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install mmv</span></span></code></pre></div><p>我们假设你在当前目录中有以下文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>a1.txt a2.txt a3.txt</span></span></code></pre></div><p>现在，你想要将所有以字母 “a” 开头的文件重命名为以 “b” 开头的。 当然，你可以在几秒钟内手动执行此操作。 但是想想你是否有数百个文件想要重命名？ 这是一个非常耗时的过程。 这时候 <code>mmv</code> 命令就很有帮助了。</p><p>要将所有以字母 “a” 开头的文件重命名为以字母 “b” 开头的，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv a\\* b\\#1</span></span></code></pre></div><p>让我们检查一下文件是否都已经重命名了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>b1.txt b2.txt b3.txt</span></span></code></pre></div><p>如你所见，所有以字母 “a” 开头的文件（即 <code>a1.txt</code>、<code>a2.txt</code>、<code>a3.txt</code>）都重命名为 <code>b1.txt</code>、<code>b2.txt</code>、<code>b3.txt</code>。</p><p><strong>解释</strong></p><p>在上面的例子中，第一个参数（<code>a\\*</code>）是 “from” 模式，第二个参数是 “to” 模式（<code>b\\#1</code>）。根据上面的例子，<code>mmv</code> 将查找任何以字母 “a” 开头的文件名，并根据第二个参数重命名匹配的文件，即 “to” 模式。我们可以使用通配符，例如用 <code>*</code>、<code>?</code> 和 <code>[]</code> 来匹配一个或多个任意字符。请注意，你必须转义使用通配符，否则它们将被 shell 扩展，<code>mmv</code> 将无法理解。</p><p>“to” 模式中的 <code>#1</code> 是通配符索引。它匹配 “from” 模式中的第一个通配符。 “to” 模式中的 <code>#2</code> 将匹配第二个通配符（如果有的话），依此类推。在我们的例子中，我们只有一个通配符（星号），所以我们写了一个 <code>#1</code>。并且，<code>#</code> 符号也应该被转义。此外，你也可以用引号括起模式。</p><p>你甚至可以将具有特定扩展名的所有文件重命名为其他扩展名。例如，要将当前目录中的所有 <code>.txt</code> 文件重命名为 <code>.doc</code> 文件格式，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv \\*.txt \\#1.doc</span></span></code></pre></div><p>这是另一个例子。 我们假设你有以下文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>abcd1.txt abcd2.txt abcd3.txt</span></span></code></pre></div><p>你希望在当前目录下的所有文件中将第一次出现的 “abc” 替换为 “xyz”。 你会怎么做呢？</p><p>很简单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv &#39;*abc*&#39; &#39;#1xyz#2&#39;</span></span></code></pre></div><p>请注意，在上面的示例中，模式被单引号括起来了。</p><p>让我们检查下 “abc” 是否实际上被替换为 “xyz”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>xyzd1.txt xyzd2.txt xyzd3.txt</span></span></code></pre></div><p>看到没？ 文件 <code>abcd1.txt</code>、<code>abcd2.txt</code> 和 <code>abcd3.txt</code> 已经重命名为 <code>xyzd1.txt</code>、<code>xyzd2.txt</code> 和 <code>xyzd3.txt</code>。</p><p><code>mmv</code> 命令的另一个值得注意的功能是你可以使用 <code>-n</code> 选项打印输出而不是重命名文件，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mmv -n a\\* b\\#1</span></span>
<span class="line"><span>a1.txt -&gt; b1.txt</span></span>
<span class="line"><span>a2.txt -&gt; b2.txt</span></span>
<span class="line"><span>a3.txt -&gt; b3.txt</span></span></code></pre></div><p>这样，你可以在重命名文件之前简单地验证 <code>mmv</code> 命令实际执行的操作。</p><p>有关更多详细信息，请参阅 man 页面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man mmv</span></span></code></pre></div><h3 id="更新-thunar-文件管理器" tabindex="-1">更新：Thunar 文件管理器 <a class="header-anchor" href="#更新-thunar-文件管理器" aria-label="Permalink to “更新：Thunar 文件管理器”">​</a></h3><p><strong>Thunar 文件管理器</strong>默认具有内置<strong>批量重命名</strong>选项。 如果你正在使用 Thunar，那么重命名文件要比使用 <code>mmv</code> 命令容易得多。</p><p>Thunar 在大多数 Linux 发行版的默认仓库库中都可用。</p><p>要在基于 Arch 的系统上安装它，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S thunar</span></span></code></pre></div><p>在 RHEL、CentOS 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install thunar</span></span></code></pre></div><p>在 Fedora 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install thunar</span></span></code></pre></div><p>在 openSUSE 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install thunar</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install thunar</span></span></code></pre></div><p>安装后，你可以从菜单或应用程序启动器中启动批量重命名程序。 要从终端启动它，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ thunar -B</span></span></code></pre></div><p>批量重命名方式如下。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/06/bulk-rename.png" alt=""></p><p>单击“+”，然后选择要重命名的文件列表。 批量重命名可以重命名文件的名称、文件的后缀或者同时重命名文件的名称和后缀。 Thunar 目前支持以下批量重命名：</p><ul><li>插入日期或时间</li><li>插入或覆盖</li><li>编号</li><li>删除字符</li><li>搜索和替换</li><li>大写或小写</li></ul><p>当你从选项列表中选择其中一个条件时，你将在“新名称”列中看到更改的预览，如下面的屏幕截图所示。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/06/bulk-rename-1.png" alt=""></p><p>选择条件后，单击“重命名文件”选项来重命名文件。</p><p>你还可以通过选择两个或更多文件从 Thunar 中打开批量重命名器。 选择文件后，按 F2 或右键单击并选择“重命名”。</p><p>嗯，这就是本次的所有内容了。希望有所帮助。更多干货即将到来。敬请关注！</p><p>祝快乐！</p><hr>`,59)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),e(t,{href:"https://www.ostechnix.com/how-to-rename-multiple-files-at-once-in-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-rename-multiple-files-at-once-in-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),e(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),e(t,{href:"https://github.com/Flowsnow"},{default:a(()=>[...s[4]||(s[4]=[i("Flowsnow",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const v=l(c,[["render",r]]);export{y as __pageData,v as default};
